begin;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,aud,role,encrypted_password,email_confirmed_at,created_at,updated_at) select ('fb710000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,'synthetic-messenger-'||x||'@fixture.invalid',jsonb_build_object('full_name','Messenger fixture','account_type_request','EXTERNAL'),'{}','authenticated','authenticated','fixture-no-password',now(),now(),now()from generate_series(1,3)x;
insert into auth.sessions(id,user_id)select('fb720000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid,('fb710000-0000-4000-8000-'||lpad(x::text,12,'0'))::uuid from generate_series(1,3)x;
insert into cbgpu_schools.schools(id,official_name,normalized_name,display_name,type,region,configuration,features,status)values('fixture-messenger-b','Messenger fixture B','messenger fixture b','Messenger B','HIGH_SCHOOL','충남','{}',array['community'],'APPROVED');
insert into cbgpu_schools.memberships(user_id,school_id,membership_type,status,verified,school_roles)values('fb710000-0000-4000-8000-000000000001','fixture-messenger-b','STUDENT','ACTIVE',true,'{}'),('fb710000-0000-4000-8000-000000000002','fixture-messenger-b','STUDENT','ACTIVE',true,'{}'),('fb710000-0000-4000-8000-000000000003','cbsh','STUDENT','ACTIVE',true,'{}');
select set_config('request.jwt.claims','{"sub":"fb710000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fb720000-0000-4000-8000-000000000001"}',true);set local role authenticated;
create temp table sent_messenger as select public.cbgpu_school_messenger_api('message_create','{"scope":"SCHOOL","school_id":"fixture-messenger-b","body":"Synthetic message","client_message_id":"fb730000-0000-4000-8000-000000000001"}')value;
do $$declare x jsonb;begin x:=public.cbgpu_school_extensions_api('message_create','{"scope":"SCHOOL","school_id":"fixture-messenger-b","body":"Synthetic message","client_message_id":"fb730000-0000-4000-8000-000000000001"}');if x->>'duplicate'<>'true'or x#>>'{message,sender_label}'is null then raise exception 'MESSENGER_RETRY_OR_COMPAT_BYPASS';end if;begin perform public.cbgpu_school_messenger_api('message_create','{"scope":"SCHOOL","school_id":"fixture-messenger-b","body":"Different message","client_message_id":"fb730000-0000-4000-8000-000000000001"}');raise exception 'MESSAGE_RETRY_CHANGED_BODY';exception when unique_violation then null;end;end$$;
select set_config('request.jwt.claims','{"sub":"fb710000-0000-4000-8000-000000000003","role":"authenticated","session_id":"fb720000-0000-4000-8000-000000000003"}',true);
do $$begin begin perform public.cbgpu_school_extensions_api('messages','{"scope":"SCHOOL","school_id":"fixture-messenger-b"}');raise exception 'CROSS_SCHOOL_MESSAGE_READ';exception when insufficient_privilege then null;end;begin perform public.cbgpu_school_messenger_api('message_mute','{"muted_user_id":"fb710000-0000-4000-8000-000000000001","muted":true}');raise exception 'UNSEEN_AUTHOR_PROBE';exception when no_data_found then null;end;end$$;
select set_config('request.jwt.claims','{"sub":"fb710000-0000-4000-8000-000000000002","role":"authenticated","session_id":"fb720000-0000-4000-8000-000000000002"}',true);
select public.cbgpu_school_messenger_api('message_mute','{"muted_user_id":"fb710000-0000-4000-8000-000000000001","muted":true}');
do $$declare x jsonb;begin x:=public.cbgpu_school_messenger_api('messages','{"scope":"SCHOOL","school_id":"fixture-messenger-b"}');if jsonb_array_length(x->'items')<>0 then raise exception 'MUTE_NOT_APPLIED';end if;x:=public.cbgpu_school_messenger_api('message_mutes');if jsonb_array_length(x->'items')<>1 then raise exception 'OWN_MUTE_LIST';end if;end$$;
select public.cbgpu_school_messenger_api('message_mute','{"muted_user_id":"fb710000-0000-4000-8000-000000000001","muted":false}');
reset role;update cbgpu_schools.memberships set status='SUSPENDED',verified=false where user_id='fb710000-0000-4000-8000-000000000001'and school_id='fixture-messenger-b';
select set_config('request.jwt.claims','{"sub":"fb710000-0000-4000-8000-000000000001","role":"authenticated","session_id":"fb720000-0000-4000-8000-000000000001"}',true);set local role authenticated;
do $$begin begin perform public.cbgpu_school_messenger_api('messages','{"scope":"SCHOOL","school_id":"fixture-messenger-b"}');raise exception 'REVOKED_MEMBER_CHAT_READ';exception when insufficient_privilege then null;end;perform public.cbgpu_school_extensions_api('message_delete',jsonb_build_object('id',(select value#>>'{message,id}'from sent_messenger)));end$$;
reset role;delete from auth.sessions where id='fb720000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"fb710000-0000-4000-8000-000000000002","role":"authenticated","session_id":"fb720000-0000-4000-8000-000000000002"}',true);set local role authenticated;
do $$begin begin perform public.cbgpu_school_messenger_api('messages','{"scope":"NATIONWIDE"}');raise exception 'REVOKED_SESSION_NATIONAL_READ';exception when insufficient_privilege then null;end;end$$;
rollback;
